import React, { Component } from 'react';
import { CButton, CCard, CCardBody, CCol, CContainer, CInput, CRow } from '@coreui/react';
import { requestHeaderGETWithAuth, requestHeaderPUTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';

const FILE_NAME = "ViewPerson.js";

class ViewPerson extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            person: null,
            error: null,
            isEditing: false,
            editName: '',
            editEmails: [''],
            editPhoneNumbers: [''],
            editDob: '',
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
        };
    }

    componentDidMount() {
        document.title = "View Person";
        this.fetchPerson();
    }

    fetchPerson() {
        const personId = this.props.match.params.personId;
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/person/' + personId;

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                logoutProcedureForLocalStorage();
                reloadPage();
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchPerson", "SUCCESS", "result", result);
            this.setState({ isLoaded: true, person: result.data });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchPerson", "ERROR", "error", error);
            this.setState({ isLoaded: true, error: error.message });
        });
    }

    startEditing = () => {
        const { person } = this.state;
        this.setState({
            isEditing: true,
            editName: person.name || '',
            editEmails: person.emails && person.emails.length > 0 ? [...person.emails] : [''],
            editPhoneNumbers: person.phoneNumbers && person.phoneNumbers.length > 0 ? [...person.phoneNumbers] : [''],
            editDob: person.dob || '',
        });
    }

    cancelEditing = () => {
        this.setState({ isEditing: false });
    }

    // Edit handlers
    handleEditEmailChange = (index, e) => {
        const editEmails = [...this.state.editEmails];
        editEmails[index] = e.target.value;
        this.setState({ editEmails });
    }

    addEditEmail = () => {
        this.setState(prev => ({ editEmails: [...prev.editEmails, ''] }));
    }

    removeEditEmail = (index) => {
        if (this.state.editEmails.length <= 1) return;
        this.setState({ editEmails: this.state.editEmails.filter((_, i) => i !== index) });
    }

    handleEditPhoneChange = (index, e) => {
        const editPhoneNumbers = [...this.state.editPhoneNumbers];
        editPhoneNumbers[index] = e.target.value;
        this.setState({ editPhoneNumbers });
    }

    addEditPhone = () => {
        this.setState(prev => ({ editPhoneNumbers: [...prev.editPhoneNumbers, ''] }));
    }

    removeEditPhone = (index) => {
        if (this.state.editPhoneNumbers.length <= 1) return;
        this.setState({ editPhoneNumbers: this.state.editPhoneNumbers.filter((_, i) => i !== index) });
    }

    saveChanges = () => {
        const { person, editName, editEmails, editPhoneNumbers, editDob } = this.state;

        const payload = {
            name: editName,
            emails: editEmails.filter(e => e.trim() !== ''),
            phoneNumbers: editPhoneNumbers.filter(p => p.trim() !== ''),
            dob: editDob || null,
        };

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/person/' + person.id;

        fetch(API_URL, requestHeaderPUTWithAuth(JSON.stringify(payload), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ loadingModalVisible: false, failureModalVisible: true });
                setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "saveChanges", "SUCCESS", "result", result);
            this.setState({
                loadingModalState: 1,
                person: result.data,
                isEditing: false,
            });
            setTimeout(() => this.setState({ loadingModalVisible: false, loadingModalState: 0 }), 800);
        })
        .catch(error => {
            Logger(FILE_NAME, "saveChanges", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    render() {
        const { isLoaded, person, error, isEditing } = this.state;

        if (!isLoaded) return <Loading />;

        if (error) {
            return (
                <div style={{ textAlign: 'center', padding: '40px', color: '#dc3545' }}>
                    <h3>Error loading person</h3>
                    <p>{error}</p>
                    <a href="#/person/create">← Back</a>
                </div>
            );
        }

        return (
            <div>
                <a href="#/persons" style={{ textDecoration: 'none' }}>
                    <CButton color="secondary" className="mb-3">← Back to Persons List</CButton>
                </a>
                <CContainer>
                    <CRow className="justify-content-center">
                        <CCol md="8">
                            <CCard className="p-4">
                                <CCardBody>
                                    {!isEditing ? this.renderViewMode() : this.renderEditMode()}
                                </CCardBody>
                            </CCard>
                        </CCol>
                    </CRow>
                </CContainer>
                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }

    renderViewMode() {
        const { person } = this.state;

        return (
            <>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h1>👤 {person.name}</h1>
                    <CButton color="primary" onClick={this.startEditing}>✏️ Edit</CButton>
                </div>
                <hr />

                <div style={styles.section}>
                    <h5>📧 Emails</h5>
                    {person.emails && person.emails.length > 0 ? (
                        <ul style={styles.list}>
                            {person.emails.map((email, i) => (
                                <li key={'email-' + i}>{email}</li>
                            ))}
                        </ul>
                    ) : (
                        <p style={styles.empty}>No emails</p>
                    )}
                </div>

                <div style={styles.section}>
                    <h5>📞 Phone Numbers</h5>
                    {person.phoneNumbers && person.phoneNumbers.length > 0 ? (
                        <ul style={styles.list}>
                            {person.phoneNumbers.map((phone, i) => (
                                <li key={'phone-' + i}>{phone}</li>
                            ))}
                        </ul>
                    ) : (
                        <p style={styles.empty}>No phone numbers</p>
                    )}
                </div>

                <div style={styles.section}>
                    <h5>🎂 Date of Birth</h5>
                    <p>{person.dob || 'Not provided'}</p>
                </div>

                <div style={styles.section}>
                    <h5>🕐 Created</h5>
                    <p>{person.createdOn ? new Date(person.createdOn).toLocaleString() : '—'}</p>
                </div>

                <div style={styles.section}>
                    <h5>🔄 Last Updated</h5>
                    <p>{person.updatedOn ? new Date(person.updatedOn).toLocaleString() : '—'}</p>
                </div>
            </>
        );
    }

    renderEditMode() {
        const { editName, editEmails, editPhoneNumbers, editDob } = this.state;

        return (
            <>
                <h2>✏️ Edit Person</h2>
                <hr />

                {/* Name */}
                <div style={styles.section}>
                    <label><strong>Name *</strong></label>
                    <CInput
                        value={editName}
                        onChange={(e) => this.setState({ editName: e.target.value })}
                        required
                    />
                </div>

                {/* Emails */}
                <div style={styles.section}>
                    <label><strong>📧 Emails</strong></label>
                    {editEmails.map((email, index) => (
                        <div key={'edit-email-' + index} style={{ display: 'flex', gap: '8px', marginBottom: '6px' }}>
                            <CInput
                                type="email"
                                value={email}
                                placeholder={'Email ' + (index + 1)}
                                onChange={(e) => this.handleEditEmailChange(index, e)}
                            />
                            {editEmails.length > 1 && (
                                <CButton color="danger" size="sm" onClick={() => this.removeEditEmail(index)}>✕</CButton>
                            )}
                        </div>
                    ))}
                    <CButton color="info" size="sm" onClick={this.addEditEmail}>+ Add Email</CButton>
                </div>

                {/* Phones */}
                <div style={styles.section}>
                    <label><strong>📞 Phone Numbers</strong></label>
                    {editPhoneNumbers.map((phone, index) => (
                        <div key={'edit-phone-' + index} style={{ display: 'flex', gap: '8px', marginBottom: '6px' }}>
                            <CInput
                                type="tel"
                                value={phone}
                                placeholder={'Phone ' + (index + 1)}
                                onChange={(e) => this.handleEditPhoneChange(index, e)}
                            />
                            {editPhoneNumbers.length > 1 && (
                                <CButton color="danger" size="sm" onClick={() => this.removeEditPhone(index)}>✕</CButton>
                            )}
                        </div>
                    ))}
                    <CButton color="info" size="sm" onClick={this.addEditPhone}>+ Add Phone</CButton>
                </div>

                {/* DOB */}
                <div style={styles.section}>
                    <label><strong>🎂 Date of Birth</strong></label>
                    <CInput
                        type="date"
                        value={editDob}
                        onChange={(e) => this.setState({ editDob: e.target.value })}
                    />
                </div>

                <hr />
                <div style={{ display: 'flex', gap: '12px' }}>
                    <CButton color="success" onClick={this.saveChanges}>💾 Save</CButton>
                    <CButton color="secondary" onClick={this.cancelEditing}>Cancel</CButton>
                </div>
            </>
        );
    }
}

const styles = {
    section: {
        marginBottom: '16px',
    },
    list: {
        paddingLeft: '20px',
        margin: 0,
    },
    empty: {
        color: '#888',
        fontStyle: 'italic',
    },
};

export default ViewPerson;
